import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Section Data Classes","description":"","frontmatter":{},"headers":[],"relativePath":"python-library/dataclasses/section.md","filePath":"python-library/dataclasses/section.md","lastUpdated":1781102819000}`),a={name:`python-library/dataclasses/section.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /python-library/dataclasses/section.md for this page in Markdown format</div><h1 id="section-data-classes" tabindex="-1">Section Data Classes <a class="header-anchor" href="#section-data-classes" aria-label="Permalink to “Section Data Classes”">​</a></h1><h2 id="reptor.models.Section.SectionRaw" tabindex="-1"><code>reptor.models.Section.SectionRaw</code> <a class="header-anchor" href="#reptor.models.Section.SectionRaw" aria-label="Permalink to “reptor.models.Section.SectionRaw”">​</a></h2><p><strong>Attributes:</strong></p><ul><li><strong><code>id</code></strong> (<code>str</code>) – Section ID (e.g., <code>scope</code>).</li><li><strong><code>created</code></strong> (<code>datetime</code>) – Section creation time (equals project creation time).</li><li><strong><code>updated</code></strong> (<code>datetime</code>) – Section last update time.</li><li><strong><code>project</code></strong> (<code>str</code>) – Project ID (uuid).</li><li><strong><code>project_type</code></strong> (<code>str</code>) – Project design ID.</li><li><strong><code>language</code></strong> (<code>str</code>) – Language code (e.g., &quot;en-US&quot;).</li><li><strong><code>label</code></strong> (<code>str</code>) – Section label (displayed in SysReptor UI).</li><li><strong><code>fields</code></strong> (<code>List[str]</code>) – List of field IDs that are used in this section (e.g., [<code>executive_summary</code>]).</li><li><strong><code>assignee</code></strong> (<code>str</code>) – User ID of the assignee.</li><li><strong><code>status</code></strong> (<code>str</code>) – Status of the section (e.g., &quot;in-progress&quot;, etc.).</li><li><strong><code>data</code></strong> (<code>SectionDataRaw</code>) – Section field data.</li></ul><p><strong>Methods:</strong></p><ul><li><strong><code>to_dict</code></strong> – Convert to a dictionary representation.</li></ul><h2 id="reptor.models.Section.SectionDataRaw" tabindex="-1"><code>reptor.models.Section.SectionDataRaw</code> <a class="header-anchor" href="#reptor.models.Section.SectionDataRaw" aria-label="Permalink to “reptor.models.Section.SectionDataRaw”">​</a></h2><p>This data class holds the section field raw values (usually, strings or lists).<br> The objects of this class may hold custom attributes, depending on your SysReptor project design and report fields.</p><p>E.g, if your project design defines a field <code>executive_summary</code> of type <code>string</code>, then this class will have an attribute <code>executive_summary</code> of type <code>str</code>.</p><p><strong>Methods:</strong></p><ul><li><strong><code>to_dict</code></strong> – Convert to a dictionary representation.</li></ul><h2 id="reptor.models.Section.Section" tabindex="-1"><code>reptor.models.Section.Section</code> <a class="header-anchor" href="#reptor.models.Section.Section" aria-label="Permalink to “reptor.models.Section.Section”">​</a></h2><p><code>Section</code> has the same attributes as <code>SectionRaw</code>, but the <code>data</code> attribute is an instance of <code>SectionData</code> class, which performs type checks and holds allowed values and other field metadata.</p><p><strong>Attributes:</strong></p><ul><li><strong><code>data</code></strong> (<code>SectionData</code>) – Section field data with type checks and metadata.</li></ul><p><strong>Methods:</strong></p><ul><li><strong><code>to_dict</code></strong> – Convert to a dictionary representation.</li></ul><h2 id="reptor.models.Section.SectionData" tabindex="-1"><code>reptor.models.Section.SectionData</code> <a class="header-anchor" href="#reptor.models.Section.SectionData" aria-label="Permalink to “reptor.models.Section.SectionData”">​</a></h2><p>This data class holds the section fields as <code>SectionDataField</code> objects.<br> The objects of this class may hold custom attributes, depending on your SysReptor project design and report fields.</p><p>E.g, if your project design defines a field <code>executive_summary</code> of type <code>string</code>, then this class will have an attribute <code>executive_summary</code> of type <code>SectionDataField</code> (which in turn specifies allowed values, etc.).</p><p><strong>Methods:</strong></p><ul><li><strong><code>to_dict</code></strong> – Convert to a dictionary representation.</li></ul><p><strong>Attributes:</strong></p><ul><li><strong><code>field_class</code></strong></li></ul><h2 id="reptor.models.Section.SectionDataField" tabindex="-1"><code>reptor.models.Section.SectionDataField</code> <a class="header-anchor" href="#reptor.models.Section.SectionDataField" aria-label="Permalink to “reptor.models.Section.SectionDataField”">​</a></h2><p><code>SectionDataField</code> holds the section field definition, metadata and its value.</p><p><strong>Attributes:</strong></p><ul><li><p><strong><code>id</code></strong> (<code>str</code>) – Section field ID (e.g., <code>executive_summary</code>).</p></li><li><p><strong><code>type</code></strong> (<code>ProjectFieldTypes</code>) – Report field type (e.g., <code>cvss</code>, <code>string</code>, <code>markdown</code>, etc.).</p></li><li><p><strong><code>label</code></strong> (<code>str</code>) – Human-readable label of the field (displayed in SysReptor UI).</p></li><li><p><strong><code>origin</code></strong> (<code>str</code>) – Field origin (one of <code>core</code>, <code>predefined</code>, <code>custom</code>)</p></li><li><p><strong><code>default</code></strong> (<code>str</code>) – Default value of the field (if any).</p></li><li><p><strong><code>required</code></strong> (<code>bool</code>) – Whether the field is required.</p></li><li><p><strong><code>spellcheck</code></strong> (<code>bool</code>) – Whether the field value should be spellchecked.</p></li><li><p><strong><code>properties</code></strong> (<code>List[ProjectDesignField]</code>) – Nested fields. Used for object fields.</p></li><li><p><strong><code>choices</code></strong> (<code>List[dict]</code>) – List of choices for enum fields.</p></li><li><p><strong><code>items</code></strong> (<code>dict</code>) – Items for list fields.</p></li><li><p><strong><code>suggestions</code></strong> (<code>List[str]</code>) – Suggestions for combobox fields.</p></li><li><p><strong><code>value</code></strong> (<code>str | List | bool | float | SectionDataField]</code>) – The value of the field. Type depends on the field type:</p></li><li><p><code>str</code>: For cvss, string, markdown, enum, user, combobox, date fields</p></li><li><p><code>List</code>: For list fields</p></li><li><p><code>bool</code>: For boolean fields</p></li><li><p><code>float</code>: For number fields</p></li><li><p><code>SectionDataField</code>: For object fields (holds nested <code>SectionDataField</code>)</p></li></ul><p><strong>Methods:</strong></p><ul><li><strong><code>to_dict</code></strong> – Convert to a dictionary representation.</li></ul><p><strong>Attributes:</strong></p><ul><li><strong><code>strict_type_check</code></strong></li></ul>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};